package pickupcode

import (
	"context"
	"crypto/rand"
	"fmt"
	"math/big"

	"github.com/jackc/pgx/v5"
)

// Create inserts a code without replacing one generated by an earlier attempt.
func Create(ctx context.Context, tx pgx.Tx, rideID string) error {
	n, err := rand.Int(rand.Reader, big.NewInt(10000))
	if err != nil {
		return fmt.Errorf("generate pickup code: %w", err)
	}
	_, err = tx.Exec(ctx, `INSERT INTO public.ride_pickup_codes (ride_id, code)
		VALUES ($1::uuid, $2) ON CONFLICT (ride_id) DO NOTHING`, rideID, fmt.Sprintf("%04d", n.Int64()))
	if err != nil {
		return fmt.Errorf("create pickup code: %w", err)
	}
	return nil
}
